import React from 'react';
import { Box, Card, CardContent, LinearProgress, Paper, Typography } from '@mui/material';
import { TrendingUp as TrendingUpIcon } from '@mui/icons-material';
import { alpha, useTheme } from '@mui/material/styles';

interface Achievement {
  title: string;
  description: string;
  level: string;
}

interface Milestone {
  title: string;
  description: string;
  currentValue: number;
  targetValue: number;
}

interface DashboardProgressCardsProps {
  achievements: Achievement[];
  milestones: Milestone[];
  getAchievementIcon: (level: string) => React.ReactNode;
}

export const DashboardProgressCards: React.FC<DashboardProgressCardsProps> = ({
  achievements,
  milestones,
  getAchievementIcon,
}) => {
  const theme = useTheme();
  const isDark = theme.palette.mode === 'dark';

  return (
    <Box
      sx={{
        display: 'grid',
        gridTemplateColumns: { xs: '1fr', md: '1fr 1fr' },
        gap: 3,
      }}
    >
      <Card sx={{ height: '100%' }}>
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
            Achievements
          </Typography>
          {achievements.length > 0 ? (
            <Box
              sx={{
                display: 'flex',
                gap: 1.5,
                overflowX: 'auto',
                pb: 0.5,
                scrollSnapType: 'x mandatory',
              }}
            >
              {achievements.map((achievement, index) => (
                <Paper
                  key={`${achievement.title}-${index}`}
                  variant="outlined"
                  sx={{
                    minWidth: 200,
                    maxWidth: 240,
                    p: 2,
                    flexShrink: 0,
                    scrollSnapAlign: 'start',
                    borderColor: alpha(theme.palette.primary.main, isDark ? 0.35 : 0.2),
                  }}
                >
                  <Box sx={{ mb: 1 }}>{getAchievementIcon(achievement.level)}</Box>
                  <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                    {achievement.title}
                  </Typography>
                  <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mt: 0.5 }}>
                    {achievement.description}
                  </Typography>
                </Paper>
              ))}
            </Box>
          ) : (
            <Typography variant="body2" color="text.secondary">
              No achievements yet. Keep working on your sustainability goals!
            </Typography>
          )}
        </CardContent>
      </Card>

      <Card sx={{ height: '100%' }}>
        <CardContent>
          <Typography variant="h6" gutterBottom sx={{ fontWeight: 700 }}>
            Next milestones
          </Typography>
          {milestones.length > 0 ? (
            <Box sx={{ display: 'flex', flexDirection: 'column', gap: 1.5 }}>
              {milestones.map((milestone, index) => {
                const pct = Math.min(100, (milestone.currentValue / milestone.targetValue) * 100);
                return (
                  <Paper
                    key={`${milestone.title}-${index}`}
                    variant="outlined"
                    sx={{ p: 2, borderColor: alpha(theme.palette.secondary.main, isDark ? 0.35 : 0.2) }}
                  >
                    <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1 }}>
                      <TrendingUpIcon color="primary" fontSize="small" sx={{ mt: 0.25 }} />
                      <Box sx={{ flex: 1, minWidth: 0 }}>
                        <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                          {milestone.title}
                        </Typography>
                        <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
                          {milestone.description}
                        </Typography>
                        <LinearProgress variant="determinate" value={pct} sx={{ height: 6, borderRadius: 3 }} />
                        <Typography variant="caption" color="text.secondary" sx={{ mt: 0.5, display: 'block' }}>
                          {milestone.currentValue} / {milestone.targetValue}
                        </Typography>
                      </Box>
                    </Box>
                  </Paper>
                );
              })}
            </Box>
          ) : (
            <Typography variant="body2" color="text.secondary">
              All milestones achieved! Great job!
            </Typography>
          )}
        </CardContent>
      </Card>
    </Box>
  );
};
